WITH updated AS (
    UPDATE "advancedbehavior" 
    SET peercorr = (peercorr - (SELECT MIN(peercorr) FROM "advancedbehavior")) / ((SELECT MAX(peercorr) FROM "advancedbehavior") - (SELECT MIN(peercorr) FROM "advancedbehavior"))
    RETURNING abhvreg, peercorr
)
SELECT abhvreg, peercorr FROM updated ORDER BY abhvreg LIMIT 10;

